import{z as o,x as A,o as E,c as d,q as s,j as i,D as t,d as l,s as n,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"Krusell–Smith","description":"","frontmatter":{"title":"Krusell–Smith","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/krusell-smith.md","filePath":"econ/krusell-smith.md","lastUpdated":1791063341000}'),m={name:"econ/krusell-smith.md"};function p(h,a,u,D,K,C){const r=A("Mermaid");return E(),d("div",null,[a[2]||(a[2]=s('<h1 id="krusell–smith" tabindex="-1">Krusell–Smith <a class="header-anchor" href="#krusell–smith" aria-label="Permalink to &quot;Krusell–Smith&quot;">​</a></h1><div class="epigraph"><p>家庭若只用资本均值（加总量冲击）预报价格，而预报误差几乎为零，无限维分布就可以被有界理性的低维状态代替。</p><footer>—— Krusell and Smith, Income and Wealth Heterogeneity in the Macroeconomy, JPE 1998</footer></div><p><a href="/econ/bewley-aiyagari">上一课</a>的不变分布在确定性总量里闭合。一旦有总量 \\(Z_t\\)，真实状态含整个 \\(\\mu_t\\)，贝尔曼的自变量无限维。本课缺口是 <strong>Krusell–Smith 近似</strong>：用少数矩当预报充分统计。不重写 Aiyagari 稳态算法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>价格 \\(r_t,w_t\\) 依赖资本总量与冲击，而资本总量是 \\(\\mu_t\\) 的积分。家庭要预报 \\(\\mu_{t+1}\\)。KS：假设家庭相信 \\(\\log K&#39;=\\alpha(Z)+\\beta(Z)\\log K\\)，只条件于今天的 \\(K\\) 与 \\(Z\\)，用模拟路径对这条定律做回归，更新信念直到自洽。若 \\(R^2\\) 极高，更高矩几乎不帮预报价格。缺口是给「分布是状态」一条可算的有界感知，而不是声称分布真的是一维。</p><p><span class="marginnote">Krusell and Smith, <em>JPE</em> 106(5), 1998, 867–896。后续：Den Haan–Rendahl 等改进模拟；Reiter 的投影把分布线性化。序列空间方法是另一条路。</span></p><p><span class="marginnote">术语翻译：「矩」是分布的汇总数——均值、方差、偏度都是矩，KS 只用第一个（资本均值）当状态。「\\(R^2\\) 极高」翻译过来就是：家庭只盯着这一个数预报明天利率，误差小到可以忽略——像只看油表指针就够开车，不必拆开引擎看每个零件。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>外层：总量定律。内层：个人 \\((a,z,K,Z)\\) 上的贝尔曼（比 Aiyagari 多两个总量状态）。模拟一大群家庭，得 \\(\\{K_t\\}\\)，再估定律。检查：把分布的其它矩加入预报，看是否改进 \\(r\\) 的预测。劳动供给、资本利用可同样处理。精度高不表示福利或分配效应可由 \\(K\\) 概括——预报价格与概括福利是两件事。</p>',9)),(E(),i(B,null,{default:t(()=>[n(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20BEL%5B%22%E4%BF%A1%E5%BF%B5%3A%20K'%20%3D%20f(K%2CZ)%22%5D%20--%3E%20V%5B%22%E5%AE%B6%E5%BA%AD%20V(a%2Cz%2CK%2CZ)%22%5D%0A%20%20V%20--%3E%20SIM%5B%22%E6%A8%A1%E6%8B%9F%E5%88%86%E5%B8%83%22%5D%0A%20%20SIM%20--%3E%20REG%5B%22%E5%9B%9E%E5%BD%92%E6%9B%B4%E6%96%B0%20f%22%5D%0A%20%20REG%20--%3E%20BEL%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与一阶 HANK：对总量冲击线性化时，分布沿确定性稳态的偏离是无限维线性系统，可用缩减或序列空间解，不必 KS 的非线性模拟。KS 仍是非线性、大冲击的基准故事。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"数字实例：政策函数在远离零资产处近似直线——存款 100 万与 101 万的家庭，储蓄行为几乎同比例；而存款 1 万、贴着借债约束的家庭，政策是弯折的，边际消费倾向高。资本总量由前者决定，所以均值够预报价格；边际消费由后者决定，所以分配效应照样大。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"机制是价格对分布的依赖几乎是通过均值（在他们的校准里）。原因：资本供给来自几乎不受约束的富人，他们接近线性政策；约束家庭的资产少，不驱动 \\(K\\)。因此总量 IRF 可以接近代表性 RBC，而分配 IRF 完全不同。这解释了「加总矩看不出异质」与「政策的分配效应很大」可以并存。",-1)),(E(),i(B,null,{default:t(()=>[n(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20RICH%5B%22%E8%B5%84%E6%9C%AC%E9%9B%86%E4%B8%AD%E5%9C%A8%E5%AF%8C%E4%BA%BA%E6%89%8B%E9%87%8C%22%5D%20--%3E%20LIN%5B%22%E5%AF%8C%E4%BA%BA%E6%94%BF%E7%AD%96%E8%BF%91%E7%BA%BF%E6%80%A7%22%5D%0A%20%20LIN%20--%3E%20KMEAN%5B%22%E6%80%BB%E8%B5%84%E6%9C%AC%20K%20%E7%94%B1%E5%9D%87%E5%80%BC%E9%A9%B1%E5%8A%A8%22%5D%0A%20%20KMEAN%20--%3E%20AGG%5B%22%E6%80%BB%E9%87%8F%20IRF%20%E8%BF%91%E4%BC%BC%E4%BB%A3%E8%A1%A8%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20POOR%5B%22%E7%A9%B7%E4%BA%BA%E8%B4%B4%E7%9D%80%E7%BA%A6%E6%9D%9F%3A%20%E6%94%BF%E7%AD%96%E5%BC%AF%E6%8A%98%22%5D%20--%3E%20MPC%5B%22%E9%AB%98%E8%BE%B9%E9%99%85%E6%B6%88%E8%B4%B9%E5%80%BE%E5%90%91%22%5D%0A%20%20MPC%20--%3E%20DIST%5B%22%E5%88%86%E9%85%8D%20IRF%20%E4%B8%8E%E6%80%BB%E9%87%8F%E4%B8%8D%E5%90%8C%22%5D%0A%20%20AGG%20--%3E%20COEX%5B%22%E4%B8%A4%E7%A7%8D%E7%8E%B0%E8%B1%A1%E5%B9%B6%E5%AD%98%2C%20%E4%B8%8D%E7%9F%9B%E7%9B%BE%22%5D%0A%20%20DIST%20--%3E%20COEX%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p>若价格依赖谁持有资产（例如抵押、住房、名义债），均值不够，KS 的 \\(R^2\\) 会掉——后课债务与 HANK 会碰到。</p><p><span class="marginnote">有界感知是求解装置，不是宣布家庭真的不做更高阶推断。太阳黑子与学习是预期单元。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 NK 粘性接上（HANK）。不讨论帕累托尾是否破坏低维预报。算法细节（模拟多少人、如何插值）不是理论。不要把 KS 写成「异质无关」：它说的是<strong>预报价格</strong>时均值够用，不是福利或 MPC。</p><p><span class="marginnote">常见误区：把 KS 读成「异质性无关紧要」。它只说预报<strong>价格</strong>时均值够用；福利、MPC、政策的分配效应不能被均值概括。而且近似有条件——若价格依赖谁持有资产（抵押、住房、名义债），\\(R^2\\) 掉下来，整套低维预报失效。</span></p><p>后课默认：有总量冲击的不完全市场，可用 KS 或线性化分布求解；加总接近代表并不取消分配。下一课：稳态财富的右尾为何比 Aiyagari 更厚。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>KS：用 \\(K\\) 与 \\(Z\\) 预报价格，自洽时 \\(R^2\\) 可极高。</li><li>总量 IRF 可像代表模型，分配效应仍在。</li><li>价格若依赖更高矩，近似失败。</li><li>出处：Krusell and Smith, <em>JPE</em> 1998。</li></ul>',8))])}const c=o(m,[["render",p]]);export{_ as __pageData,c as default};
